# Rebuild everything in one cell

def gf3_points():
    points = []
    for x in range(3):
        for y in range(3):
            for z in range(3):
                if (x, y, z) == (0, 0, 0):
                    continue
                if x != 0:
                    inv_x = pow(x, -1, 3)
                    p = (1, (y * inv_x) % 3, (z * inv_x) % 3)
                elif y != 0:
                    inv_y = pow(y, -1, 3)
                    p = (0, 1, (z * inv_y) % 3)
                else:
                    p = (0, 0, 1)
                if p not in points:
                    points.append(p)
    return points

def dot_gf3(p, l):
    return (p[0]*l[0] + p[1]*l[1] + p[2]*l[2]) % 3

points = gf3_points()
lines = gf3_points()

