def bfs_girth(adj, n):
    min_cycle = float('inf')
    for start in range(n):
        dist = [-1] * n
        dist[start] = 0
        queue = [start]
        qi = 0
        while qi < len(queue):
            u = queue[qi]; qi += 1
            for w in adj[u]:
                if dist[w] == -1:
                    dist[w] = dist[u] + 1
                    queue.append(w)
                elif dist[w] >= dist[u]:  # Back edge, not parent direction
                    cycle_len = dist[u] + dist[w] + 1
                    if cycle_len < min_cycle:
                        min_cycle = cycle_len
    return min_cycle

